<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Register — Solomon</title><link rel="stylesheet" href="assets/css/main.css"></head><body><main class="panel"><h1>CREATE PLAYER</h1><form id="form"><input name="username" placeholder="Username" required><input name="email" type="email" placeholder="Email" required><input name="password" type="password" placeholder="Password (8+ chars)" required><button class="btn">CREATE ACCOUNT</button><p id="msg"></p></form><a href="login.php">Login</a></main><script>form.onsubmit=async e=>{e.preventDefault();let r=await fetch('api/register.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))});let d=await r.json();msg.textContent=d.message||'Created';if(d.success)location.href='dashboard.php';}</script></body></html>
